// The real-looking person shown in Photo view. Order of preference:
//   1. a base photo from the library in public/models (listed in manifest.json),
//      picked by sex, skin tone group and build: free and instant;
//   2. one this browser already generated for the same look;
//   3. a new one generated by the server.
import { makePersonPhoto } from '../api.js';

const BASE = (import.meta.env && import.meta.env.BASE_URL) || '/';
const STORE = 'fitcheck.people.v1';
const KEEP = 4;

const SKIN_GROUP = {
  porcelain: 'light', light: 'light', 'light-medium': 'light',
  olive: 'medium', medium: 'medium', tan: 'medium',
  brown: 'dark', deep: 'dark', rich: 'dark',
};
const BUILDS = ['slim', 'average', 'heavy'];

export function buildOf({ heightCm, weightKg }) {
  const bmi = (Number(weightKg) || 70) / ((Number(heightCm) || 175) / 100) ** 2;
  return bmi < 21 ? 'slim' : bmi < 28 ? 'average' : 'heavy';
}

const round5 = (n) => Math.round((Number(n) || 0) / 5) * 5;
/** Same look -> same key, so small slider nudges don't make a new person. */
export const personKey = (a) => JSON.stringify([a.sex, a.skin, a.hairStyle, a.hairColor, round5(a.heightCm), round5(a.weightKg)]);

let library = null;
const loadLibrary = () =>
  (library ||= fetch(`${BASE}models/manifest.json`)
    .then((r) => (r.ok ? r.json() : []))
    .catch(() => []));

/** Closest library photo: same sex and skin group required, nearest build wins. */
export function pickBase(list, avatar) {
  const skin = SKIN_GROUP[avatar.skin] || 'medium';
  const build = BUILDS.indexOf(buildOf(avatar));
  const fits = list.filter((p) => p.sex === avatar.sex && (p.skin === avatar.skin || p.skin === skin));
  fits.sort((a, b) =>
    Math.abs(BUILDS.indexOf(a.build) - build) - Math.abs(BUILDS.indexOf(b.build) - build) || (b.skin === avatar.skin) - (a.skin === avatar.skin)
  );
  const best = fits[0];
  return best && Math.abs(BUILDS.indexOf(best.build) - build) <= 1 ? best : null;
}

const toDataUrl = (blob) =>
  new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => resolve(r.result);
    r.onerror = reject;
    r.readAsDataURL(blob);
  });

function readSaved() {
  try {
    return JSON.parse(localStorage.getItem(STORE)) || [];
  } catch {
    return [];
  }
}
function save(key, image) {
  try {
    const list = [[key, image], ...readSaved().filter(([k]) => k !== key)].slice(0, KEEP);
    localStorage.setItem(STORE, JSON.stringify(list));
  } catch {
    // Storage full or blocked: it just gets regenerated next time.
  }
}

/** Returns { image (data URL), source: 'library' | 'generated' }. */
export async function personPhoto(avatar) {
  const base = pickBase(await loadLibrary(), avatar);
  if (base) {
    const res = await fetch(`${BASE}models/${base.file}`);
    if (res.ok) return { image: await toDataUrl(await res.blob()), source: 'library' };
  }
  const key = personKey(avatar);
  const saved = readSaved().find(([k]) => k === key);
  if (saved) return { image: saved[1], source: 'generated' };
  const image = await makePersonPhoto(avatar);
  save(key, image);
  return { image, source: 'generated' };
}
